int binarySearch(const int piArr[], int iSize, int iTarget)
{
    int iLow = 0;
    int iHigh = iSize - 1;
    while (iLow <= iHigh)
    {
        int iMid = (iLow + iHigh) / 2;
        if (piArr[iMid] == iTarget) return iMid;
        else if (iTarget < piArr[iMid]) iHigh = iMid - 1;
        else iLow = iMid + 1;
    }
    return -1;
}

